import { Parameters } from './Parameters';

class Individual {
	public width: number;
	public length: number;
	public height: number;
	public fitness: number = 0;

	constructor(width?: number, length?: number, height?: number) {
		this.width = width || 0;
		this.length = length || 0;
		this.height = height || 0;
	}
	public clone(): Individual {
		const copy = new Individual(this.width, this.length, this.height);
		copy.fitness = this.fitness;
		return copy;
	}
}
interface GeneticAlgorithmConfig {
	populationSize: number;
	generations: number;
	mutationRate: number;
	crossoverRate: number;
	elitismRate: number;
	targetVolume: number;
	tolerance: number;
	dimension: Parameters;
}
export class GeneticAlgorithm {
	private config: GeneticAlgorithmConfig;
	private population: Individual[] = [];
	private dimension: Parameters;
	private bestIndividual: Individual | null = null;
	private generationHistory: { generation: number; bestFitness: number; avgFitness: number }[] = [];

	private needLog = false;

	constructor(config: Partial<GeneticAlgorithmConfig> = {}) {
		this.config = {
			populationSize: 100,
			generations: 1000,
			mutationRate: 0.1,
			crossoverRate: 0.8,
			elitismRate: 0.2,
			targetVolume: 2000,
			tolerance: 10,
			dimension: new Parameters(),
			...config,
		};

		this.dimension = this.config.dimension;
	}
	private createRandomIndividual(): Individual {
		const constraints = this.dimension.constraint;

		const width = this.randomInRange(constraints.width.min, constraints.width.max);
		const length = this.randomInRange(constraints.length.min, constraints.length.max);
		const height = this.randomInRange(constraints.height.min, constraints.height.max);

		return new Individual(width, length, height);
	}
	private randomInRange(min: number, max: number): number {
		return Math.random() * (max - min) + min;
	}
	private initializePopulation(): void {
		this.population = [];
		for (let i = 0; i < this.config.populationSize; i++) {
			this.population.push(this.createRandomIndividual());
		}
	}
	private calculateFitness(individual: Individual): number {
		this.dimension.setSize(individual.width, individual.height, individual.length);
		const actualVolume = parseFloat(this.dimension.getVolumeApproximate());
		const volumeDifference = Math.abs(actualVolume - this.config.targetVolume);
		return 1 / (1 + volumeDifference);
	}
	private evaluatePopulation(): void {
		for (const individual of this.population) {
			individual.fitness = this.calculateFitness(individual);
		}
		this.population.sort((a, b) => b.fitness - a.fitness);

		if (!this.bestIndividual || this.population[0].fitness > this.bestIndividual.fitness) {
			this.bestIndividual = this.population[0].clone();
		}
	}
	private tournamentSelection(tournamentSize: number = 5): Individual {
		const tournament: Individual[] = [];

		for (let i = 0; i < tournamentSize; i++) {
			const randomIndex = Math.floor(Math.random() * this.population.length);
			tournament.push(this.population[randomIndex]);
		}

		return tournament.reduce((best, current) => (current.fitness > best.fitness ? current : best));
	}
	private crossover(parent1: Individual, parent2: Individual): Individual[] {
		if (Math.random() > this.config.crossoverRate) {
			return [parent1.clone(), parent2.clone()];
		}

		const child1 = new Individual();
		const child2 = new Individual();

		if (Math.random() < 0.5) {
			child1.width = parent1.width;
			child2.width = parent2.width;
		} else {
			child1.width = parent2.width;
			child2.width = parent1.width;
		}

		if (Math.random() < 0.5) {
			child1.length = parent1.length;
			child2.length = parent2.length;
		} else {
			child1.length = parent2.length;
			child2.length = parent1.length;
		}

		if (Math.random() < 0.5) {
			child1.height = parent1.height;
			child2.height = parent2.height;
		} else {
			child1.height = parent2.height;
			child2.height = parent1.height;
		}

		return [child1, child2];
	}
	private mutate(individual: Individual): void {
		const constraints = this.dimension.constraint;

		if (Math.random() < this.config.mutationRate) {
			const mutationStrength = 2.0;
			individual.width = this.clamp(individual.width + (Math.random() - 0.5) * mutationStrength, constraints.width.min, constraints.width.max);
		}

		if (Math.random() < this.config.mutationRate) {
			const mutationStrength = 2.0;
			individual.length = this.clamp(individual.length + (Math.random() - 0.5) * mutationStrength, constraints.length.min, constraints.length.max);
		}

		if (Math.random() < this.config.mutationRate) {
			const mutationStrength = 2.0;
			individual.height = this.clamp(individual.height + (Math.random() - 0.5) * mutationStrength, constraints.height.min, constraints.height.max);
		}
	}
	private clamp(value: number, min: number, max: number): number {
		return Math.max(min, Math.min(max, value));
	}
	private selectElites(): Individual[] {
		const eliteCount = Math.floor(this.config.populationSize * this.config.elitismRate);
		return this.population.slice(0, eliteCount).map((ind) => ind.clone());
	}
	private calculateGenerationStats(generation: number): void {
		const avgFitness = this.population.reduce((sum, ind) => sum + ind.fitness, 0) / this.population.length;
		const bestFitness = this.population[0].fitness;

		this.generationHistory.push({
			generation,
			bestFitness,
			avgFitness,
		});
	}
	public optimize(): Individual {
		if (this.needLog) {
			console.log(`Starting Genetic Algorithm Optimization...`);
			console.log(`Target Volume: ${this.config.targetVolume}`);
			console.log(`Population Size: ${this.config.populationSize}`);
			console.log(`Generations: ${this.config.generations}`);
		}
		this.initializePopulation();

		for (let generation = 0; generation < this.config.generations; generation++) {
			this.evaluatePopulation();
			this.calculateGenerationStats(generation);

			if (this.isTargetReached()) {
				if (this.needLog) {
					console.log(`Target reached at generation ${generation}!`);
				}
				break;
			}

			if (generation % 100 === 0) {
				this.printProgress(generation);
			}

			const newPopulation: Individual[] = [];

			const elites = this.selectElites();
			newPopulation.push(...elites);

			while (newPopulation.length < this.config.populationSize) {
				const parent1 = this.tournamentSelection();
				const parent2 = this.tournamentSelection();

				const [child1, child2] = this.crossover(parent1, parent2);

				this.mutate(child1);
				this.mutate(child2);

				newPopulation.push(child1);
				if (newPopulation.length < this.config.populationSize) {
					newPopulation.push(child2);
				}
			}

			this.population = newPopulation;
		}
		this.evaluatePopulation();

		if (this.needLog) {
			console.log('\nOptimization Complete!');
		}
		this.printFinalResult();

		return this.bestIndividual!;
	}
	private isTargetReached(): boolean {
		if (!this.bestIndividual) return false;

		this.dimension.setSize(this.bestIndividual.width, this.bestIndividual.height, this.bestIndividual.length);
		const actualVolume = parseFloat(this.dimension.getVolumeApproximate());
		const difference = Math.abs(actualVolume - this.config.targetVolume);

		return difference <= this.config.tolerance;
	}
	private printProgress(generation: number): void {
		if (!this.bestIndividual) return;

		this.dimension.setSize(this.bestIndividual.width, this.bestIndividual.height, this.bestIndividual.length);
		const actualVolume = parseFloat(this.dimension.getVolumeApproximate());
		const difference = Math.abs(actualVolume - this.config.targetVolume);

		if (this.needLog) {
			console.log(`Generation ${generation}: Best Volume = ${actualVolume}, Target = ${this.config.targetVolume}, Difference = ${difference.toFixed(2)}`);
		}
	}
	private printFinalResult(): void {
		if (!this.bestIndividual) return;

		this.dimension.setSize(this.bestIndividual.width, this.bestIndividual.height, this.bestIndividual.length);
		const actualVolume = parseFloat(this.dimension.getVolumeApproximate());
		const difference = Math.abs(actualVolume - this.config.targetVolume);

		if (this.needLog) {
			console.log('\n=== FINAL RESULT ===');
			console.log(`Width: ${this.bestIndividual.width.toFixed(2)}`);
			console.log(`Length: ${this.bestIndividual.length.toFixed(2)}`);
			console.log(`Height: ${this.bestIndividual.height.toFixed(2)}`);
			console.log(`Actual Volume: ${actualVolume}`);
			console.log(`Target Volume: ${this.config.targetVolume}`);
			console.log(`Difference: ${difference.toFixed(2)}`);
			console.log(`Fitness: ${this.bestIndividual.fitness.toFixed(6)}`);
		}
	}
	public getGenerationHistory(): { generation: number; bestFitness: number; avgFitness: number }[] {
		return this.generationHistory;
	}
}

export const runOptimization = (targetVolume: number = 2000, dimension: Parameters): Individual => {
	const ga = new GeneticAlgorithm({
		populationSize: 100,
		generations: 1000,
		mutationRate: 0.1,
		crossoverRate: 0.8,
		elitismRate: 0.2,
		targetVolume: targetVolume,
		tolerance: 10,
		dimension: dimension,
	});

	return ga.optimize();
};
